579	// StartTestTemporary500Server creates a server that returns 500 for a duration, then recovers
580	// Uses slow transfer to ensure the file isn't fully downloaded during resolve phase
581	func StartTestTemporary500Server(errorDuration time.Duration) net.Listener {
582		startTime := time.Now()
583		var requestCount atomic.Int32
