873	type shutdownListener struct {
874		server     *http.Server
875		isShutdown bool
876		net.Listener
877	}
878	
879	func (c *shutdownListener) Close() error {
880		// Shutdown server first (waits for in-flight requests), then set isShutdown
881		closeErr := c.server.Shutdown(context.Background())
882		c.isShutdown = true
883		if err := ifExistAndRemove(BuildFile); err != nil {
884			fmt.Println(err)
885		}
886		if err := ifExistAndRemove(DownloadFile); err != nil {
887			fmt.Println(err)
888		}
889		if err := ifExistAndRemove(DownloadRenameFile); err != nil {
890			fmt.Println(err)
891		}
892		return closeErr
893	}
894	
895	func ifExistAndRemove(name string) error {
896		if _, err := os.Stat(name); !os.IsNotExist(err) {
897			return os.Remove(name)
898		}
899		return nil
900	}
